using System;using System.Xml.Linq;
static class NativeHeaderFixture {
internal static XElement Valid(){var root=new XElement("nativeHeader",new XAttribute("version",1),new XAttribute("required",1));foreach(var key in new[]{"team","deathTime","homeX","homeY","homeZ","homeRange","clientId","sleeperPose","stunKnee","stunProne","stunType","headState","bodyPart","focusedSlot","holdingMode","statWait","statNetWait"})root.SetAttributeValue(key,0);foreach(var key in new[]{"lifetime","size","headSize","stunDuration","statEnclosed","statBuffRemainder"})root.SetAttributeValue(key,"1");foreach(var key in new[]{"ground","sleeper","passiveSleeper","sleeping","dancing","spawnShare","crawler","nameNull","spawnNameNull"})root.SetAttributeValue(key,"0");root.SetAttributeValue("name","Medic");root.SetAttributeValue("spawnName","");root.SetAttributeValue("belongsKind","none");root.SetAttributeValue("belongsKey","-1");root.SetAttributeValue("spawnKind","none");root.SetAttributeValue("spawnKey","0");return root;}
internal static int Run(){int count=0;Action<bool,string> check=(b,s)=>{if(!b)throw new Exception(s);count++;};check(RebirthNpcNativeHeader.TryRead(Valid(),out var header),"valid complete native header");var copy=header.Write();copy.SetAttributeValue("name","Other");check(header.Text("name")=="Medic","native header immutable");foreach(var attribute in Valid().Attributes()){var broken=Valid();broken.Attribute(attribute.Name).Remove();check(!RebirthNpcNativeHeader.TryRead(broken,out _),"missing mandatory header "+attribute.Name);}
foreach(var pair in new[]{("team","01"),("team","+1"),("lifetime","NaN"),("lifetime","Infinity"),("size","1.0"),("ground","true"),("clientId","42"),("holdingMode","2"),("focusedSlot","4096"),("belongsKind","npc"),("belongsKey","42"),("spawnKind","unknown"),("spawnKind","npc"),("nameNull","1")}){var broken=Valid();broken.SetAttributeValue(pair.Item1,pair.Item2);check(!RebirthNpcNativeHeader.TryRead(broken,out _),"malformed header "+pair.Item1+pair.Item2);}
var good=Valid();good.SetAttributeValue("belongsKind","player");good.SetAttributeValue("belongsKey","Steam_example_server_owned_identity");check(RebirthNpcNativeHeader.TryRead(good,out _),"player identity carried without granting native integer");good=Valid();good.SetAttributeValue("spawnKind","npc");good.SetAttributeValue("spawnKey",new RebirthNpcStableId(1,1));check(RebirthNpcNativeHeader.TryRead(good,out _),"actual stable NPC creator id accepted");
var legacy=Program.HeaderMigrationRoot();check(RebirthNpcNativeReconstruction.TryRead(legacy,out var old)&&!old.HasNativeHeader,"schema1 retained header unresolved");legacy.SetAttributeValue("version",2);check(!RebirthNpcNativeReconstruction.TryRead(legacy,out _),"schema2 cannot silently default missing header");legacy.Add(Valid());check(RebirthNpcNativeReconstruction.TryRead(legacy,out var modern)&&modern.HasNativeHeader&&XNode.DeepEquals(modern.Write(),legacy),"schema2 exact composed header roundtrip");var extra=modern.Write();extra.Add(Valid());check(!RebirthNpcNativeReconstruction.TryRead(extra,out _),"duplicate header refused");extra=modern.Write();extra.SetAttributeValue("version",1);check(!RebirthNpcNativeReconstruction.TryRead(extra,out _),"schema1 refuses new required header adjacency");return count;}}